    def __init__(self, weight: np.ndarray, epsilon: float) -> None:
        if weight.ndim != 1:
            raise ValueError("RMSNorm weight must have shape [D]")
        if epsilon <= 0:
            raise ValueError("RMSNorm epsilon must be positive")
        self.weight = weight
        self.epsilon = epsilon

    def __call__(self, hidden_states: np.ndarray) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.shape[-1] != self.weight.shape[0]:
            raise ValueError("hidden size does not match RMSNorm weight")
        values = hidden_states.astype(np.float32, copy=False)
        mean_square = np.mean(np.square(values), axis=-1, keepdims=True)
        return values * np.reciprocal(np.sqrt(mean_square + self.epsilon)) * self.weight


class Linear:
    """Apply a learned projection to the last tensor dimension."""

    def __init__(self, weight: np.ndarray, bias: np.ndarray | None = None) -> None:
        if weight.ndim != 2:
            raise ValueError("linear weight must have shape [O,I]")
        if bias is not None and bias.shape != (weight.shape[0],):
            raise ValueError("linear bias must have shape [O]")
        self.weight = weight
        self.bias = bias

    def __call__(self, hidden_states: np.ndarray) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.shape[-1] != self.weight.shape[1]:
            raise ValueError("input size does not match linear weight")
        output = hidden_states @ self.weight.T
        return output if self.bias is None else output + self.bias

"""Rotary position embeddings for Qwen3 attention."""

from __future__ import annotations

import numpy as np


class RotaryEmbedding:
    """Build the cosine and sine values used to rotate attention heads."""

    def __init__(self, head_dim: int, theta: float = 1_000_000.0) -> None:
        if isinstance(head_dim, bool) or not isinstance(head_dim, int) or head_dim <= 0:
            raise ValueError("RoPE head dimension must be a positive integer")
        if head_dim % 2:
            raise ValueError("RoPE head dimension must be even")
        if theta <= 0:
            raise ValueError("RoPE theta must be positive")
        dimensions = np.arange(0, head_dim, 2, dtype=np.float32)
        self.inverse_frequencies = 1.0 / (theta ** (dimensions / head_dim))

    def __call__(self, position_ids: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        position_ids = np.asarray(position_ids)
        if position_ids.ndim != 2:
            raise ValueError("position IDs must have shape [B,S]")
        if not np.issubdtype(position_ids.dtype, np.integer):
            raise ValueError("position IDs must be integers")
        if np.any(position_ids < 0):
            raise ValueError("position IDs must be non-negative")
        angles = position_ids.astype(np.float32)[..., None] * self.inverse_frequencies
        angles = np.concatenate((angles, angles), axis=-1)
        return np.cos(angles), np.sin(angles)


def _rotate_half(hidden_states: np.ndarray) -> np.ndarray:
    first_half, second_half = np.split(hidden_states, 2, axis=-1)
    return np.concatenate((-second_half, first_half), axis=-1)


def apply_rotary_position_embedding(
    query: np.ndarray,
    key: np.ndarray,
    cosine: np.ndarray,
    sine: np.ndarray,
) -> tuple[np.ndarray, np.ndarray]:
    """Rotate Query and Key while allowing different Q and KV head counts."""

    query = np.asarray(query)
    key = np.asarray(key)
    cosine = np.asarray(cosine)
    sine = np.asarray(sine)
    if query.ndim != 4 or key.ndim != 4:
        raise ValueError("Query and Key must have shape [B,H,S,Hd]")
    if query.shape[0] != key.shape[0] or query.shape[2:] != key.shape[2:]:
        raise ValueError("Query and Key must share batch, sequence, and head dimensions")
    expected = (query.shape[0], query.shape[2], query.shape[3])
    if cosine.shape != expected or sine.shape != expected:
        raise ValueError("RoPE cosine and sine must have shape [B,S,Hd]")
    cosine = cosine[:, None, :, :]
    sine = sine[:, None, :, :]
    rotated_query = query * cosine + _rotate_half(query) * sine
    rotated_key = key * cosine + _rotate_half(key) * sine
    return rotated_query, rotated_key

"""Read named tensors from a Safetensors checkpoint."""

from __future__ import annotations

import json
import math
import struct
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import numpy as np


_DTYPE_WIDTHS = {
    "BF16": 2,
    "F16": 2,
    "F32": 4,
    "I32": 4,
    "I64": 8,
}

_NUMPY_DTYPES = {
    "F16": np.dtype("<f2"),
    "F32": np.dtype("<f4"),
    "I32": np.dtype("<i4"),
    "I64": np.dtype("<i8"),
}


@dataclass(frozen=True, slots=True)
class TensorInfo:
    """Where one tensor lives inside one Safetensors shard."""

    name: str
    dtype: str
    shape: tuple[int, ...]
    shard: str
    data_offsets: tuple[int, int]
    data_start: int


class SafetensorsCheckpoint:
    """A name-to-tensor view over one or more Safetensors files."""

    def __init__(self, directory: Path, tensors: dict[str, TensorInfo]) -> None:
        self.directory = directory
        self._tensors = tensors

    @classmethod
    def from_directory(cls, directory: str | Path) -> "SafetensorsCheckpoint":
        root = Path(directory)
        index_files = sorted(root.glob("*.safetensors.index.json"))
        if index_files:
            tensors = _read_index(root, index_files[0])
        else:
            shards = sorted(root.glob("*.safetensors"))
            if len(shards) != 1:
                raise ValueError("expected one Safetensors file or one index")
            tensors = _read_shard(shards[0])
        return cls(root, tensors)

    def keys(self) -> tuple[str, ...]:
        return tuple(sorted(self._tensors))

    def tensor_info(self, name: str) -> TensorInfo:
        try:
            return self._tensors[name]
        except KeyError as error:
            raise KeyError(f"unknown tensor: {name}") from error

    def load_tensor(self, name: str) -> np.ndarray:
        """Read one tensor payload instead of loading the whole checkpoint."""

        info = self.tensor_info(name)
        start, end = info.data_offsets
        with (self.directory / info.shard).open("rb") as handle:
            handle.seek(info.data_start + start)
            payload = handle.read(end - start)
        if len(payload) != end - start:
            raise ValueError(f"tensor payload is truncated: {name}")

        if info.dtype == "BF16":
            words = np.frombuffer(payload, dtype="<u2").astype(np.uint32)
            array = (words << 16).view(np.float32)
        else:
            array = np.frombuffer(payload, dtype=_NUMPY_DTYPES[info.dtype]).copy()
        return array.reshape(info.shape)


def _read_index(root: Path, path: Path) -> dict[str, TensorInfo]:
    index = json.loads(path.read_text(encoding="utf-8"))
    weight_map = index.get("weight_map")
    if not isinstance(weight_map, dict):
        raise ValueError("Safetensors index must contain weight_map")

    shard_headers = {
        shard_name: _read_shard(root / shard_name)
        for shard_name in sorted(set(weight_map.values()))
    }
    tensors: dict[str, TensorInfo] = {}
    for name, shard_name in weight_map.items():
        try:
            tensors[name] = shard_headers[shard_name][name]
        except KeyError as error:
            raise ValueError(f"index points to a missing tensor: {name}") from error
    return tensors


def _read_shard(path: Path) -> dict[str, TensorInfo]:
    with path.open("rb") as handle:
        prefix = handle.read(8)
        if len(prefix) != 8:
            raise ValueError(f"invalid Safetensors file: {path.name}")
        (header_length,) = struct.unpack("<Q", prefix)
        header = json.loads(handle.read(header_length))

    data_start = 8 + header_length
    data_size = path.stat().st_size - data_start
    tensors: dict[str, TensorInfo] = {}
    for name, metadata in header.items():
        if name != "__metadata__":
            tensors[name] = _tensor_info(
                name, metadata, path.name, data_start, data_size
            )
    return tensors


def _tensor_info(
    name: str,
    metadata: Any,
    shard: str,
    data_start: int,
    data_size: int,
) -> TensorInfo:
    dtype = metadata["dtype"]
    shape = tuple(metadata["shape"])
    start, end = metadata["data_offsets"]
    if dtype not in _DTYPE_WIDTHS:
        raise ValueError(f"unsupported Safetensors dtype: {dtype}")
    if start < 0 or end > data_size:
        raise ValueError(f"tensor offsets are outside {shard}: {name}")
    expected_bytes = math.prod(shape) * _DTYPE_WIDTHS[dtype]
    if end - start != expected_bytes:
        raise ValueError(f"tensor shape does not match its byte range: {name}")
    return TensorInfo(name, dtype, shape, shard, (start, end), data_start)

"""Encode text with the byte-level BPE stored in a Qwen3 tokenizer.json."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Iterable

import regex


class Qwen3Tokenizer:
    """A small, inference-only reader for Qwen3 byte-level BPE assets."""

    def __init__(
        self,
        vocabulary: dict[str, int],
        merges: list[str | list[str]],
        pretoken_pattern: str,
        special_tokens: dict[str, int],
    ) -> None:
        self.vocabulary = vocabulary
        self.tokens = {token_id: token for token, token_id in vocabulary.items()}
        self.special_tokens = special_tokens
        self.special_token_ids = frozenset(special_tokens.values())
        self._merge_ranks = {
            self._parse_merge(pair): rank for rank, pair in enumerate(merges)
        }
        self._pretokenizer = regex.compile(pretoken_pattern)
        self._special_pattern = (
            regex.compile(
                "|".join(
                    regex.escape(token)
                    for token in sorted(special_tokens, key=len, reverse=True)
                )
            )
            if special_tokens
            else None
        )
        self._byte_encoder, self._byte_decoder = _byte_alphabet()
        self._bpe_cache: dict[str, tuple[str, ...]] = {}

    @classmethod
    def from_file(cls, path: str | Path) -> "Qwen3Tokenizer":
        """Read the vocabulary, merge ranks, and special tokens."""

        raw = json.loads(Path(path).read_text(encoding="utf-8"))
        model = raw.get("model")
        if not isinstance(model, dict) or model.get("type") != "BPE":
            raise ValueError("tokenizer.json must contain a BPE model")
        vocabulary = model.get("vocab")
        merges = model.get("merges")
        if not isinstance(vocabulary, dict) or not isinstance(merges, list):
            raise ValueError("tokenizer.json is missing its vocabulary or merges")
        if not all(
            isinstance(token, str) and isinstance(token_id, int)
            for token, token_id in vocabulary.items()
        ):
            raise ValueError("tokenizer vocabulary must map strings to integer IDs")

        special_tokens = {
            item["content"]: item["id"]
            for item in raw.get("added_tokens", [])
            if item.get("special") is True
        }
        full_vocabulary = {**vocabulary, **special_tokens}
        if len(set(full_vocabulary.values())) != len(full_vocabulary):
            raise ValueError("tokenizer IDs must be unique")
        return cls(
            full_vocabulary,
            merges,
            _find_split_pattern(raw.get("pre_tokenizer")),
            special_tokens,
        )

    @staticmethod
    def _parse_merge(pair: str | list[str]) -> tuple[str, str]:
        parts = pair.split(" ", 1) if isinstance(pair, str) else pair
        if len(parts) != 2:
            raise ValueError(f"invalid BPE merge: {pair!r}")
        return parts[0], parts[1]

    @property
    def vocab_size(self) -> int:
        return len(self.vocabulary)

    def token_to_id(self, token: str) -> int:
        try:
            return self.vocabulary[token]
        except KeyError as error:
            raise KeyError(f"unknown token: {token!r}") from error

    def id_to_token(self, token_id: int) -> str:
        try:
            return self.tokens[token_id]
        except KeyError as error:
            raise KeyError(f"unknown token ID: {token_id}") from error

    def encode(self, text: str) -> list[int]:
        """Turn text into the exact token IDs used to index model embeddings."""

        if self._special_pattern is None:
            return self._encode_text(text)

        token_ids: list[int] = []
        start = 0
        for match in self._special_pattern.finditer(text):
            token_ids.extend(self._encode_text(text[start : match.start()]))
            token_ids.append(self.special_tokens[match.group(0)])
            start = match.end()
        token_ids.extend(self._encode_text(text[start:]))
        return token_ids

    def _encode_text(self, text: str) -> list[int]:
        token_ids: list[int] = []
        for match in self._pretokenizer.finditer(text):
            byte_token = "".join(
                self._byte_encoder[byte] for byte in match.group(0).encode("utf-8")
            )
            pieces = self._bpe_cache.get(byte_token)
            if pieces is None:
                pieces = _merge_token(byte_token, self._merge_ranks)
                self._bpe_cache[byte_token] = pieces
            try:
                token_ids.extend(self.vocabulary[piece] for piece in pieces)
            except KeyError as error:
                raise ValueError(f"BPE produced an unknown token: {error.args[0]!r}") from error
        return token_ids

    def decode(
        self,
        token_ids: Iterable[int],
        *,
        skip_special_tokens: bool = False,
        errors: str = "replace",
    ) -> str:
        """Reassemble token IDs into UTF-8 text."""

        output: list[str] = []
        byte_buffer = bytearray()

        def flush_bytes() -> None:
            if byte_buffer:
                output.append(byte_buffer.decode("utf-8", errors=errors))
                byte_buffer.clear()

        for token_id in token_ids:
            token = self.id_to_token(token_id)
            if token_id in self.special_token_ids:
                flush_bytes()
                if not skip_special_tokens:
                    output.append(token)
                continue
            try:
                byte_buffer.extend(self._byte_decoder[character] for character in token)
            except KeyError as error:
                raise ValueError(
                    f"token contains a character outside the byte alphabet: {token!r}"
                ) from error
        flush_bytes()
        return "".join(output)


def _byte_alphabet() -> tuple[dict[int, str], dict[str, int]]:
    """Map all 256 byte values to visible Unicode characters and back."""

    byte_values = list(range(ord("!"), ord("~") + 1))
    byte_values += list(range(ord("¡"), ord("¬") + 1))
    byte_values += list(range(ord("®"), ord("ÿ") + 1))
    code_points = byte_values.copy()
    extra = 0
    for byte in range(256):
        if byte not in byte_values:
            byte_values.append(byte)
            code_points.append(256 + extra)
            extra += 1
    encoder = dict(zip(byte_values, map(chr, code_points), strict=True))
    return encoder, {character: byte for byte, character in encoder.items()}


def _merge_token(
    token: str, merge_ranks: dict[tuple[str, str], int]
) -> tuple[str, ...]:
    """Repeatedly apply the highest-priority merge still present in one token."""

    pieces = tuple(token)
    while len(pieces) > 1:
        adjacent_pairs = zip(pieces, pieces[1:])
        best_pair = min(adjacent_pairs, key=lambda pair: merge_ranks.get(pair, float("inf")))
        if best_pair not in merge_ranks:
            break

        merged: list[str] = []
        index = 0
        while index < len(pieces):
            if index + 1 < len(pieces) and pieces[index : index + 2] == best_pair:
                merged.append("".join(best_pair))
                index += 2
            else:
                merged.append(pieces[index])
                index += 1
        pieces = tuple(merged)
    return pieces


def _find_split_pattern(pretokenizer: object) -> str:
    if not isinstance(pretokenizer, dict):
        raise ValueError("tokenizer.json is missing its pre-tokenizer")
    if pretokenizer.get("type") == "Split":
        pattern = pretokenizer.get("pattern")
        if isinstance(pattern, dict) and isinstance(pattern.get("Regex"), str):
            return pattern["Regex"]
    for child in pretokenizer.get("pretokenizers", []):
        try:
            return _find_split_pattern(child)
        except ValueError:
            pass
    raise ValueError("tokenizer.json does not contain a regex Split pre-tokenizer")

"""Small NumPy layers shared by Qwen3 MoE inference modules."""

from __future__ import annotations

import numpy as np


class Embedding:
    """Look up one hidden vector for every token ID."""

    def __init__(self, weight: np.ndarray) -> None:
        if weight.ndim != 2:
            raise ValueError("embedding weight must have shape [V,D]")
        self.weight = weight

    def __call__(self, token_ids: np.ndarray) -> np.ndarray:
        token_ids = np.asarray(token_ids)
        if not np.issubdtype(token_ids.dtype, np.integer):
            raise ValueError("token IDs must be integers")
        if np.any(token_ids < 0) or np.any(token_ids >= self.weight.shape[0]):
            raise ValueError("token ID is outside the embedding vocabulary")
        return self.weight[token_ids]


class RMSNorm:
    """Scale hidden states by their root-mean-square magnitude."""

    def __init__(self, weight: np.ndarray, epsilon: float) -> None:
        if weight.ndim != 1:
            raise ValueError("RMSNorm weight must have shape [D]")
        if epsilon <= 0:
            raise ValueError("RMSNorm epsilon must be positive")
        self.weight = weight
        self.epsilon = epsilon

    def __call__(self, hidden_states: np.ndarray) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.shape[-1] != self.weight.shape[0]:
            raise ValueError("hidden size does not match RMSNorm weight")
        values = hidden_states.astype(np.float32, copy=False)
        mean_square = np.mean(np.square(values), axis=-1, keepdims=True)
        return values * np.reciprocal(np.sqrt(mean_square + self.epsilon)) * self.weight


class Linear:
    """Apply a learned projection to the last tensor dimension."""

    def __init__(self, weight: np.ndarray, bias: np.ndarray | None = None) -> None:
        if weight.ndim != 2:
            raise ValueError("linear weight must have shape [O,I]")
        if bias is not None and bias.shape != (weight.shape[0],):
            raise ValueError("linear bias must have shape [O]")
        self.weight = weight
        self.bias = bias

    def __call__(self, hidden_states: np.ndarray) -> np.ndarray:
        hidden_states = np.asarray(hidden_states)
        if hidden_states.shape[-1] != self.weight.shape[1]:
            raise ValueError("input size does not match linear weight")
        output = hidden_states @ self.weight.T
        return output if self.bias is None else output + self.bias

"""Rotary position embeddings for Qwen3 attention."""

from __future__ import annotations

import numpy as np


class RotaryEmbedding:
    """Build the cosine and sine values used to rotate attention heads."""

    def __init__(self, head_dim: int, theta: float = 1_000_000.0) -> None:
        if isinstance(head_dim, bool) or not isinstance(head_dim, int) or head_dim <= 0:
            raise ValueError("RoPE head dimension must be a positive integer")
        if head_dim % 2:
            raise ValueError("RoPE head dimension must be even")
        if theta <= 0:
            raise ValueError("RoPE theta must be positive")
        dimensions = np.arange(0, head_dim, 2, dtype=np.float32)
        self.inverse_frequencies = 1.0 / (theta ** (dimensions / head_dim))

    def __call__(self, position_ids: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        position_ids = np.asarray(position_ids)
        if position_ids.ndim != 2:
            raise ValueError("position IDs must have shape [B,S]")
        if not np.issubdtype(position_ids.dtype, np.integer):
            raise ValueError("position IDs must be integers")
        if np.any(position_ids < 0):
            raise ValueError("position IDs must be non-negative")
        angles = position_ids.astype(np.float32)[..., None] * self.inverse_frequencies
        angles = np.concatenate((angles, angles), axis=-1)
        return np.cos(angles), np.sin(angles)


def _rotate_half(hidden_states: np.ndarray) -> np.ndarray:
    first_half, second_half = np.split(hidden_states, 2, axis=-1)
    return np.concatenate((-second_half, first_half), axis=-1)


def apply_rotary_position_embedding(
    query: np.ndarray,
    key: np.ndarray,
    cosine: np.ndarray,
    sine: np.ndarray,
) -> tuple[np.ndarray, np.ndarray]:
    """Rotate Query and Key while allowing different Q and KV head counts."""

    query = np.asarray(query)
    key = np.asarray(key)
    cosine = np.asarray(cosine)
    sine = np.asarray(sine)
    if query.ndim != 4 or key.ndim != 4:
        raise ValueError("Query and Key must have shape [B,H,S,Hd]")
    if query.shape[0] != key.shape[0] or query.shape[2:] != key.shape[2:]:
        raise ValueError("Query and Key must share batch, sequence, and head dimensions")
    expected = (query.shape[0], query.shape[2], query.shape[3])
    if cosine.shape != expected or sine.shape != expected:
        raise ValueError("RoPE cosine and sine must have shape [B,S,Hd]")
    cosine = cosine[:, None, :, :]
    sine = sine[:, None, :, :]
    rotated_query = query * cosine + _rotate_half(query) * sine
    rotated_key = key * cosine + _rotate_half(key) * sine
    return rotated_query, rotated_key
